/bin/bash -lc "python - <<'PY'
from PyQt5.QtCore import QUrl
u=QUrl('http://localhost/%3A5?q=%3A10#%3A20')
for name in ('host','path','query','fragment'):
 getter=getattr(u,name)
 print(name, repr(getter()), repr(getter(QUrl.FullyEncoded)))
for mode in (QUrl.DecodedMode,QUrl.FullyEncoded,QUrl.StrictMode):
 v=QUrl(u)
 try:
  v.setPath('/%3A6',mode)
  print('mode',int(mode),v.toString(QUrl.FullyEncoded))
 except Exception as e: print('mode error',int(mode),type(e).__name__,e)
PY"

