/bin/bash -lc "python - <<'PY'
from PyQt5.QtCore import QUrl
u=QUrl('http://ho%73t2.example:42/%2f4?q=%3a5#%2e6')
print('whole',u.toString(QUrl.FullyEncoded))
for name in ('host','path','query','fragment'):
 print(name,repr(getattr(u,name)(QUrl.FullyEncoded)))
for name,val in [('setHost','ho%73t3.example'),('setPath','/%2f5'),('setQuery','q=%3a6'),('setFragment','%2e7')]:
 v=QUrl(u)
 try:
  getattr(v,name)(val,QUrl.StrictMode)
  print(name,repr(v.toString(QUrl.FullyEncoded)))
 except Exception as e: print(name,type(e).__name__,str(e))
PY"

